          "code": "import random


def _make_sentence(vocabulary, target_words, k=10):
    """Generate one sentence of k words from vocabulary and underscore
    any target words that appear in it."""
    if len(vocabulary) >= k:
        words = random.sample(list(vocabulary), k)
    else:
        # Vocabulary smaller than the required word count: sample with replacement
        words = random.choices(list(vocabulary), k=k)
    sentence = ' '.join(words)

    if target_words:
        # Replace longer targets first so that multi-word targets nested inside
        # other targets are handled sensibly.
        for target in sorted(target_words, key=len, reverse=True):
            target_str = str(target)
            if target_str in sentence:
                sentence = sentence.replace(target_str, target_str.replace(' ', '_'))
    return sentence


def generate_report(data):
    """
    Process multiple sets of (target_words, n_sentences, vocabulary) and
    generate a report of processed sentences.

    Parameters
    ----------
    data : iterable
        Each item describes one processing set and may be:
          * a tuple/list: (target_words, n_sentences, vocabulary)
          * a dict with keys: 'target_words', 'n_sentences', 'vocabulary'
            (the keys 'targets', 'num_sentences', and 'vocab' are also accepted)

    Returns
    -------
    dict
        Keys are identifiers ('set_0', 'set_1', ...) for each input set.
        Values are the corresponding lists of processed sentences, or an
        error message string when the set is invalid (negative n_sentences
        or empty vocabulary).
    """
    report = {}
    for idx, entry in enumerate(data):
        key = 'set_{}'.format(idx)
        try:
            if isinstance(entry, dict):
                target_words = entry.get('target_words', entry.get('targets'))
                n_sentences = entry.get('n_sentences', entry.get('num_sentences'))
                vocabulary = entry.get('vocabulary', entry.get('vocab'))
            else:
                target_words, n_sentences, vocabulary = entry

            n_sentences = int(n_sentences)
            vocabulary = list(vocabulary)
            target_words = list(target_words) if target_words else []

            # Exception handling for invalid inputs
            if n_sentences < 0:
                raise ValueError('n_sentences must be non-negative')
            if not vocabulary:
                raise ValueError('vocabulary must not be empty')

            sentences = [
                _make_sentence(vocabulary, target_words)
                for _ in range(n_sentences)
            ]
            report[key] = sentences
        except (ValueError, TypeError) as exc:
            report[key] = 'Error: {}'.format(exc)
    return report
